/// so one generated bridge serves every Atomiverse precision configuration.
/// The Frame materialization boundary performs any required storage-tier
/// conversion. See the corrosion wiring in the root CMakeLists.txt.
#pragma once

// Generated by corrosion_add_cxxbridge — molrs coordinates are f64.
#include "molrs_cxx/bridge.h"

// `molrs::Element` is emitted by molrs-cxxapi from molrs' canonical Rust
// periodic table. Callers use the owning namespace directly; Atomiverse does
// not re-export or alias the type.
